export interface TagInputProps {
  value: string[];
  onChange: (tags: string[]) => void;
  maxTags?: number;
  placeholder?: string;
}

function normalize(tags: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of tags) {
    const tag = raw.trim();
    if (!tag) continue;
    const key = tag.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(tag);
  }
  return result;
}

export default function TagInput({
  value,
  onChange,
  maxTags,
  placeholder = "Add tag…",
}: TagInputProps) {
  const [draft, setDraft] = useState("");
  const [notice, setNotice] = useState("");

  const atLimit = maxTags !== undefined && value.length >= maxTags;

  function addTags(raw: string[]) {
    const candidates = normalize(raw);
    if (candidates.length === 0) return;

    let accepted: string[] = [];
    let rejected = 0;

    for (const tag of candidates) {
      const duplicate = value.some(
        (existing) => existing.toLowerCase() === tag.toLowerCase(),
      );
      if (duplicate) continue;
      if (maxTags !== undefined && value.length + accepted.length >= maxTags) {
        rejected += candidates.length - accepted.length - (candidates.length - candidates.indexOf(tag) - 1 ? 0 : 0);
        rejected = candidates.filter(
          (_, i) => i >= candidates.indexOf(tag),
        ).length;
        break;
      }
      accepted.push(tag);
    }

    if (accepted.length > 0) {
      onChange([...value, ...accepted]);
      setNotice("");
    }
    if (rejected > 0 || (accepted.length === 0 && atLimit)) {
      setNotice(`Maximum of ${maxTags} tags reached.`);
    }
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter" || event.key === ",") {
      event.preventDefault();
      addTags([draft]);
      setDraft("");
      return;
    }
    if (
      event.key === "Backspace" &&
      draft === "" &&
      !event.nativeEvent.isComposing
    ) {
      event.preventDefault();
      if (value.length > 0) {
        onChange(value.slice(0, -1));
        setNotice("");
      }
    }
  }

  function handlePaste(event: ClipboardEvent<HTMLInputElement>) {
    const text = event.clipboardData.getData("text");
    if (!text.includes(",")) return;
    event.preventDefault();
    addTags(text.split(","));
  }

  function removeTag(tag: string) {
    onChange(value.filter((t) => t !== tag));
    setNotice("");
  }

  return (
    <div className="tag-input">
      <ul className="tag-input__chips">
        {value.map((tag) => (
          <li key={tag} className="tag-input__chip">
            {tag}{" "}
            <button type="button" onClick={() => removeTag(tag)}>
              Remove {tag}
            </button>
          </li>
        ))}
      </ul>
      <input
        type="text"
        aria-label="Add tag"
        placeholder={placeholder}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
      />
      {notice && <p role="status">{notice}</p>}
    </div>
  );
}
"})
