result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tags/TagInput.test.tsx", "content": "import { useState } from "react";
import { cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, it, vi } from "vitest";

import TagInput from "./TagInput";

afterEach(cleanup);

describe("TagInput", () => {
  function Harness({
    initial = [],
    maxTags,
    onChange,
  }: {
    initial?: string[];
    maxTags?: number;
    onChange?: (tags: string[]) => void;
  }) {
    const [tags, setTags] = useState<string[]>(initial);
    return (
      <TagInput
        value={tags}
        onChange={(next) => {
          setTags(next);
          onChange?.(next);
        }}
        maxTags={maxTags}
      />
    );
  }

  async function typeAndCommit(text: string, commit: "{enter}" | ",") {
    const input = screen.getByLabelText("Add tag");
    await userEvent.type(input, text);
    await userEvent.type(input, commit);
  }

  it("adds a trimmed tag on Enter and clears the field", async () => {
    render(<Harness />);
    await typeAndCommit("  react  ", "{enter}");
    expect(screen.getByText("react")).toBeInTheDocument();
    expect(screen.getByLabelText("Add tag")).toHaveValue("");
  });

  it("adds a tag on comma", async () => {
    render(<Harness />);
    await typeAndCommit("react", ",");
    expect(screen.getByText("react")).toBeInTheDocument();
  });

  it("does not add empty or whitespace-only tags", async () => {
    render(<Harness />);
    await typeAndCommit("   ", "{enter}");
    await userEvent.type(screen.getByLabelText("Add tag"), ",");
    expect(screen.queryByRole("listitem")).not.toBeInTheDocument();
  });

  it("deduplicates case-insensitively against existing chips", async () => {
    render(<Harness />);
    await typeAndCommit("React", "{enter}");
    await typeAndCommit("REACT", "{enter}");
    const chips = screen.getAllByRole("listitem");
    expect(chips).toHaveLength(1);
    expect(chips[0]).toHaveTextContent("React");
  });

  it("removes the last chip on Backspace in an empty field", async () => {
    render(<Harness initial={["one", "two"]} />);
    const input = screen.getByLabelText("Add tag");
    expect(screen.getAllByRole("listitem")).toHaveLength(2);

    await userEvent.type(input, "{backspace}");
    expect(screen.getAllByRole("listitem").map((li) => li.textContent)).toEqual([
      "onetwoRemove one",
    ]);

    await userEvent.type(input, "{backspace}");
    expect(screen.queryByRole("listitem")).not.toBeInTheDocument();
  });

  it("does not remove anything on Backspace when the field has text", async () => {
    render(<Harness initial={["keep"]} />);
    await userEvent.type(screen.getByLabelText("Add tag"), "abc{backspace}");
    expect(screen.getAllByRole("listitem")).toHaveLength(1);
    expect(screen.getByLabelText("Add tag")).toHaveValue("ab");
  });

  it("removes a chip via its labelled remove button", async () => {
    const onChange = vi.fn();
    render(<Harness initial={["react", "vue"]} onChange={onChange} />);

    await userEvent.click(screen.getByRole("button", { name: "Remove react" }));

    expect(onChange).toHaveBeenCalledWith(["vue"]);
    expect(screen.queryByText("react")).not.toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Remove vue" })).toBeInTheDocument();
  });

  it("blocks additions past maxTags and shows a status message", async () => {
    render(<Harness initial={["a"]} maxTags={2} />);
    await typeAndCommit("b", "{enter}");
    expect(screen.getAllByRole("listitem")).toHaveLength(2);
    expect(
      screen.queryByRole("status"),
    ).not.toBeInTheDocument();

    await typeAndCommit("c", "{enter}");
    expect(screen.getAllByRole("listitem")).toHaveLength(2);
    const status = screen.getByRole("status");
    expect(status).toHaveTextContent(/maximum of 2 tags/i);
  });

  it("pastes a comma-separated string and adds multiple tags at once", async () => {
    render(<Harness />);
    const input = screen.getByLabelText("Add tag");
    await userEvent.click(input);
    await userEvent.paste("react, vue,  angular ");
    const chips = screen.getAllByRole("listitem");
    expect(chips.map((li) => li.textContent)).toEqual([
      "reactRemove react",
      "vueRemove vue",
      "angularRemove angular",
    ]);
    expect(input).toHaveValue("");
  });

  it("paste dedupes case-insensitively within the batch and against existing tags", async () => {
    render(<Harness initial={["React"]} />);
    await userEvent.click(screen.getByLabelText("Add tag"));
    await userEvent.paste("VUE, vue, REACT");
    expect(screen.getAllByRole("listitem").map((li) => li.textContent)).toEqual([
      "ReactRemove React",
      "VUERemove VUE",
    ]);
  });

  it("paste respects the remaining capacity under maxTags and reports it", async () => {
    render(<Harness initial={["a", "b", "c"]} maxTags={4} />);
    await userEvent.click(screen.getByLabelText("Add tag"));
    await userEvent.paste("d, e");
    expect(screen.getAllByRole("listitem")).toHaveLength(4);
    expect(screen.getByRole("status")).toHaveTextContent(/maximum of 4 tags/i);
  });

  it("is fully controlled: parent state drives what is rendered", async () => {
    const onChange = vi.fn();
    render(<Harness onChange={onChange} />);
    await typeAndCommit("react", "{enter}");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(["react"]);
    // chip visible only because the harness stored it via onChange
    expect(screen.getByText("react")).toBeInTheDocument();
  });
});
"})
